import React, { useEffect } from 'react';
import { dbService } from '../../services/api';

/**
 * AiDynamicOverrideInjector
 * Dynamically injects live CSS themes, custom styles, and UI configs
 * requested by the user and generated by Ai Manezar (Gemini 3 Flash).
 * Backed by 60-day RecycleBin snapshots for 1-click safe rollback.
 */
export const AiDynamicOverrideInjector: React.FC = () => {
  useEffect(() => {
    let isMounted = true;

    const applyOverrides = async () => {
      try {
        const res = await dbService.ai.getOverrides();
        if (!isMounted || !res.success || !Array.isArray(res.overrides)) return;

        // 1. Get or create <style id="ai-dynamic-css">
        let styleTag = document.getElementById('ai-dynamic-css') as HTMLStyleElement | null;
        if (!styleTag) {
          styleTag = document.createElement('style');
          styleTag.id = 'ai-dynamic-css';
          document.head.appendChild(styleTag);
        }

        // 2. Concatenate all active CSS rules
        const activeCssRules = res.overrides
          .filter((o) => (o.isActive === 1 || o.isActive === true) && (o.overrideType === 'CSS_THEME' || o.overrideType === 'CUSTOM_CSS'))
          .map((o) => `/* AI Override [${o.targetKey}]: */\n${o.content}`)
          .join('\n\n');

        styleTag.textContent = activeCssRules;

        // 3. Expose UI configs on window for components to optionally read
        const uiConfigs = res.overrides
          .filter((o) => (o.isActive === 1 || o.isActive === true) && o.overrideType === 'UI_CONFIG')
          .reduce((acc, curr) => {
            try {
              acc[curr.targetKey] = JSON.parse(curr.content);
            } catch {
              acc[curr.targetKey] = curr.content;
            }
            return acc;
          }, {} as Record<string, any>);

        (window as any).MAHA_AI_UI_CONFIGS = uiConfigs;
      } catch (err) {
        console.warn('[AiDynamicOverrideInjector] Failed to apply overrides:', err);
      }
    };

    applyOverrides();

    const handleOverrideUpdated = () => {
      applyOverrides();
    };

    window.addEventListener('maha-ai-override-updated', handleOverrideUpdated);
    return () => {
      isMounted = false;
      window.removeEventListener('maha-ai-override-updated', handleOverrideUpdated);
    };
  }, []);

  return null;
};
